add('P7394','版本树回溯与同深度子树计数',
    '回到历史状态的操作把事件连成版本树。DFS 版本树时切换灯并在退出时撤销。距离为偶数 2d 的同深度点，属于 x 的 d 级祖先子树，却不属于通往 x 的那个孩子子树。',
    '同深度两点距离必为偶数。若 y=2d，目标点与 x 的 LCA 必须是 x 的 d 级祖先 A。d=0 时只有 x；d>0 时答案是 A 子树中当前深度的亮灯数减去孩子 B 子树中该深度的亮灯数，B 是 x 的 d−1 级祖先。d 超过 x 深度或 y 为奇数时为零。\n\nEuler 序使子树连续。按深度分组保存每个点的 Euler 位置，并为每层建立 Fenwick，亮灯是单点修改，某深度子树计数通过二分区间端点后查询。\n\n普通事件 i 继承 i−1 的版本，回退事件继承指定历史 x，得到一棵版本树。DFS 进入修改事件时翻转对应灯，退出时再翻转一次撤销；查询事件只记录答案。版本树与原树都用迭代遍历，最终按事件原顺序输出查询结果。',
    '时间 O((n+m) log n)，空间 O(n+m)。','距离奇数直接零；回退指向事件后的版本；退出修改事件时必须撤销。',r'''
int n;cin>>n;vector<vector<int>>g(n);for(int i=1;i<n;i++){int a,b;cin>>a>>b;a--;b--;g[a].push_back(b);g[b].push_back(a);}HLD tree(g);vector<vector<int>>positions(n);vector<int>rank(n);for(int p=0;p<n;p++){int v=tree.at[p],d=tree.depth[v];rank[v]=positions[d].size()+1;positions[d].push_back(p);}vector<Fenwick>bits;bits.reserve(n);for(auto&v:positions)bits.emplace_back(v.size());int m;cin>>m;struct Op{int type=0,x=0,y=0;};vector<Op>ops(m+1);vector<vector<int>>versions(m+1);for(int i=1;i<=m;i++){cin>>ops[i].type>>ops[i].x;int parent=i-1;if(ops[i].type==3)parent=ops[i].x;else{ops[i].x--;if(ops[i].type==2)cin>>ops[i].y;}versions[parent].push_back(i);}vector<int>light(n),ans(m+1);auto flip=[&](int v){light[v]^=1;bits[tree.depth[v]].add(rank[v],light[v]?1:-1);};auto count=[&](int root,int depth){auto&v=positions[depth];int l=lower_bound(v.begin(),v.end(),tree.pos[root])-v.begin(),r=lower_bound(v.begin(),v.end(),tree.pos[root]+tree.size[root])-v.begin();return bits[depth].sum(r)-bits[depth].sum(l);};vector<pair<int,bool>>st={{0,false}};while(!st.empty()){auto[event,leave]=st.back();st.pop_back();auto op=ops[event];if(leave){if(op.type==1)flip(op.x);continue;}if(op.type==1)flip(op.x);else if(op.type==2){int x=op.x,y=op.y;if(y%2==0&&y/2<=tree.depth[x]){int d=y/2;if(!d)ans[event]=light[x];else ans[event]=count(tree.jump(x,d),tree.depth[x])-count(tree.jump(x,d-1),tree.depth[x]);}}st.push_back({event,true});for(int child:versions[event])st.push_back({child,false});}for(int i=1;i<=m;i++)if(ops[i].type==2)cout<<ans[i]<<'\n';
''',HLD+FENWICK)

add('P5568','坐标加倍表示开闭端点，懒标记维护集合',
    '整数点映射到偶数位置，两个整数间的开区间映射到奇数位置。五种集合运算变成区间置零、置一、翻转及清空区间外，最后合并连续被选位置。',
    '将 [a,b] 编为 [2a,2b]，左开则左端加一，右开则右端减一。奇位置代表两个相邻整数间的整段开区间，因此可以同时保存端点与端点间的选中状态。\n\nU 将 T 内置一，D 置零，S 翻转；I 清空 T 外，C 清空 T 外并翻转 T 内。空 T 对 U、D、S 无影响，对 I、C 则清空整个集合。\n\n线段树维护赋值标记和翻转标记。赋值覆盖旧翻转，翻转若遇到已有赋值就直接改零一；否则异或翻转位。操作完成后下传得到每个加倍位置的状态，合并连续选中段，偶端点输出闭括号，奇端点输出对应整数的开括号。',
    '设坐标域 V=131071，时间 O(M log V+V)，空间 O(V)。','C 是 T−S；开端点调整一格；空区间的 I/C 清空所有内容。',r'''
const int V=131071;vector<int>assign(4*V,0);vector<char>flip(4*V);auto apply=[&](int v,int type){if(type<2){assign[v]=type;flip[v]=0;}else if(assign[v]>=0)assign[v]^=1;else flip[v]^=1;};function<void(int)>push=[&](int v){if(assign[v]>=0){apply(v*2,assign[v]);apply(v*2+1,assign[v]);assign[v]=-1;}if(flip[v]){apply(v*2,2);apply(v*2+1,2);flip[v]=0;}};function<void(int,int,int,int,int,int)>update=[&](int v,int l,int r,int L,int R,int type){if(L>R)return;if(L<=l&&r<=R){apply(v,type);return;}push(v);int mid=(l+r)/2;if(L<=mid)update(v*2,l,mid,L,R,type);if(R>mid)update(v*2+1,mid+1,r,L,R,type);};char op,left,right,comma;int a,b;while(cin>>op>>left>>a>>comma>>b>>right){int L=2*a+(left=='('),R=2*b-(right==')');if(L>R){if(op=='I'||op=='C')apply(1,0);continue;}if(op=='I'||op=='C'){update(1,0,V-1,0,L-1,0);update(1,0,V-1,R+1,V-1,0);}if(op=='U')update(1,0,V-1,L,R,1);if(op=='D')update(1,0,V-1,L,R,0);if(op=='S'||op=='C')update(1,0,V-1,L,R,2);}vector<char>chosen(V);function<void(int,int,int)>collect=[&](int v,int l,int r){if(assign[v]>=0){fill(chosen.begin()+l,chosen.begin()+r+1,assign[v]);return;}push(v);int mid=(l+r)/2;collect(v*2,l,mid);collect(v*2+1,mid+1,r);};collect(1,0,V-1);bool any=false;for(int l=0;l<V;){if(!chosen[l]){l++;continue;}int r=l;while(r+1<V&&chosen[r+1])r++;if(any)cout<<' ';any=true;cout<<(l%2?'(':'[')<<l/2<<','<<(r+1)/2<<(r%2?')':']');l=r+1;}if(!any)cout<<"empty set";cout<<'\n';
''')

add('P10134','记录位约束下尽量晚地抬高未知分数',
    '每个 h 必须成为新的前缀最大值，而 a+1..h−1 禁止出现新纪录。先标出这些约束，再按 h 从小到大处理：若中间已知值太高，抬高 a 之前最靠后的可修改纪录位置，最后让 h 刚好超过此前最大值。',
    '对记忆 (a,h)，条件等价于 max(c1..ca)=max(c1..c[h−1])，且 c[h] 严格更大。相同 h 只需保留最小 a；区间 a+1..h−1 中都不能产生新前缀纪录，而 h 必须产生纪录。必创纪录点落在禁创区间时立即矛盾。\n\n未知值先置一，保留“原本未知且不禁止创纪录”的位置有序集合。按 h 递增处理，设 a 前最大值为 M，中间 a+1..h−1 最大值为 need。若 need>M，必须在一到 a 抬高一个原未知位置；为了字典序最小，选择可行的最右位置并只抬到 need。禁创纪录位置不能用，因为抬到超过 M 必然违反已有纪录约束。\n\n之后 h 若未知，设为此前最大值加一；若已知，就检查是否已经严格更大。线段树支持区间最大值和单点抬高。后来的被迫抬高若破坏早先固定纪录，完整复核会发现矛盾；最右可改位置已涵盖所有更晚可用纪录点，换更早位置不能避开这种矛盾。\n\n最终检查所有原记忆与 C 上限。每个抬高都是由不可更改的中间值或必须出现的新纪录强制，且总选最晚位置、最小必要值，所以可行时得到字典序最小序列。',
    '时间 O((N+Q) log N)，空间 O(N+Q)。','相同 h 取最小 a；原已知值不能改；最终复核全部记忆和数值上限。',r'''
int T;cin>>T;while(T--){int n,q;long long C;cin>>n>>q>>C;vector<long long>a(n+1),original(n+1);for(int i=1;i<=n;i++){cin>>original[i];a[i]=original[i]?original[i]:1;}vector<pair<int,int>>constraints(q);vector<int>first(n+1,n+1),diff(n+3);for(auto&[l,h]:constraints){cin>>l>>h;first[h]=min(first[h],l);}for(int h=1;h<=n;h++)if(first[h]<=n){diff[first[h]+1]++;diff[h]--;}vector<char>forbidden(n+1);int active=0;bool ok=true;set<int>changeable;for(int i=1;i<=n;i++){active+=diff[i];forbidden[i]=active>0;if(first[i]<=n&&forbidden[i])ok=false;if(!original[i]&&!forbidden[i])changeable.insert(i);}int size=1;while(size<n)size*=2;vector<long long>tree(2*size);for(int i=1;i<=n;i++)tree[size+i-1]=a[i];for(int i=size-1;i;i--)tree[i]=max(tree[i*2],tree[i*2+1]);auto query=[&](int l,int r){long long ans=0;for(l+=size-1,r+=size;l<r;l/=2,r/=2){if(l&1)ans=max(ans,tree[l++]);if(r&1)ans=max(ans,tree[--r]);}return ans;};auto setValue=[&](int i,long long value){a[i]=value;int p=size+i-1;tree[p]=value;for(p/=2;p;p/=2)tree[p]=max(tree[p*2],tree[p*2+1]);};for(int h=1;h<=n&&ok;h++)if(first[h]<=n){int l=first[h];long long before=query(1,l),need=query(l+1,h-1);if(need>before){auto it=changeable.upper_bound(l);if(it==changeable.begin()){ok=false;break;}--it;setValue(*it,need);}long long maximum=query(1,h-1);if(!original[h])setValue(h,maximum+1);else if(a[h]<=maximum)ok=false;}for(int i=1;i<=n;i++)if(a[i]>C)ok=false;for(auto[l,h]:constraints)if(query(1,l)!=query(1,h-1)||a[h]<=query(1,l))ok=false;if(!ok)cout<<-1<<'\n';else for(int i=1;i<=n;i++)cout<<a[i]<<(i==n?'\n':' ');}
''')

LCE=r'''
struct LCE{int n,size;vector<int>rank,tree;
 LCE(const string&s):n(s.size()),rank(n){vector<int>sa(n),r(n),tmp(n),y(n),count(max(257,n+1));int classes=256;for(int i=0;i<n;i++){r[i]=(unsigned char)s[i]+1;count[r[i]]++;}for(int i=1;i<=classes;i++)count[i]+=count[i-1];for(int i=n-1;i>=0;i--)sa[--count[r[i]]]=i;
 for(int gap=1;gap<n;gap*=2){int z=0;for(int i=max(0,n-gap);i<n;i++)y[z++]=i;for(int v:sa)if(v>=gap)y[z++]=v-gap;fill(count.begin(),count.begin()+classes+1,0);for(int v:y)count[r[v]]++;for(int i=1;i<=classes;i++)count[i]+=count[i-1];for(int i=n-1;i>=0;i--)sa[--count[r[y[i]]]]=y[i];int nextClasses=1;tmp[sa[0]]=1;for(int i=1;i<n;i++){int a=sa[i-1],b=sa[i];if(r[a]!=r[b]||(a+gap<n?r[a+gap]:0)!=(b+gap<n?r[b+gap]:0))nextClasses++;tmp[b]=nextClasses;}r.swap(tmp);classes=nextClasses;if(classes==n)break;}
 for(int i=0;i<n;i++)rank[sa[i]]=i;vector<int>height(n);for(int i=0,h=0;i<n;i++){int at=rank[i];if(!at){h=0;continue;}int j=sa[at-1];while(i+h<n&&j+h<n&&s[i+h]==s[j+h])h++;height[at]=h;if(h)h--;}
 size=1;while(size<n)size*=2;tree.assign(2*size,n);for(int i=0;i<n;i++)tree[size+i]=height[i];for(int i=size-1;i;i--)tree[i]=min(tree[i*2],tree[i*2+1]);}
 int query(int a,int b)const{if(a==b)return n-a;int l=rank[a],r=rank[b];if(l>r)swap(l,r);int ans=n;for(l+=size+1,r+=size+1;l<r;l/=2,r/=2){if(l&1)ans=min(ans,tree[l++]);if(r&1)ans=min(ans,tree[--r]);}return ans;}
};
'''

add('P13790','一次字符修改只能修复一条或两条相邻比较边',
    '长度 n−d 的 border 等价于 s[i]=s[i+d]。一次改字只会影响同余链中至多两条比较边。用正反 Z 找首末失配，再分一条失配与两条相邻失配检查，LCE 核对中间没有其它失配。',
    '固定移位 d，把位置按模 d 分成若干链，每条边比较相距 d 的字符。改一个字符只影响它左右两条链边。因此所有失配必须集中在一条边，或两条拥有同一个中间顶点的相邻边。\n\n正向 Z[d] 给首失配 l，反串 Z[d] 给末失配 r。无失配则原本成立。只有一条失配 l=r 时，必须修改链的端点才能不破坏其它相等边，也就是 l<d 或 l+2d≥n。\n\n有两条时，必须 r=l+d，且两外端字符 s[l]、s[l+2d] 相同，才能把中间改成它们。还要确认首末之间其它比较都相等，即 LCE(l+1,l+d+1)≥d−1。首末之外已由正反 Z 保证。\n\nLCE 使用后缀数组、相邻 LCP 与区间最小值树，完全确定性，不依赖哈希。按 d 从小到大检查，首个成功对应最大真 border；没有成功则零。',
    '时间 O(n log n)，空间 O(n)。','一次改字最多影响两条比较；一条失配必须有可改链端；border 必须短于原串。',r'''
string s;cin>>s;int n=s.size();auto z=zfunction(s);string reverseS=s;reverse(reverseS.begin(),reverseS.end());auto rz=zfunction(reverseS);unique_ptr<LCE>lce;for(int d=1;d<n;d++){int length=n-d,l=z[d];bool ok=false;if(l>=length)ok=true;else{int r=length-1-rz[d];if(l==r)ok=l<d||l+2*d>=n;else if(r==l+d&&s[l]==s[l+2*d]){if(d==1)ok=true;else{if(!lce)lce=make_unique<LCE>(s);ok=lce->query(l+1,l+d+1)>=d-1;}}}if(ok){cout<<n-d<<'\n';return 0;}}cout<<0<<'\n';
''',ZFUNCTION+LCE)

add('CF379D','只枚举首尾字母与 AC 数量',
    '两串拼接的 AC 数只等于两边内部 AC 数加一次边界判断。因此每个初始串只需记录首字母、末字母和 AC 个数。先生成每种可行描述的一条串，再枚举两串描述模拟递推。',
    '拼接 X+Y 的新增匹配只有边界：当 X 末尾 A、Y 开头 C 时加一。其它内部匹配保持不变，所以长度再大也只需保存首尾与计数。\n\n对给定初始长度，用字母 A、B、C 动态生成可行的 (首,尾,数量) 状态，并保留一条构造串。其它大写字母都可换成 B，因为它们既不形成 AC，也不会改变 A、C 的边界作用。\n\n枚举两个可行描述，按题目 s_i=s_(i−2)+s_(i−1) 推出第 k 项，计数超过目标可截断为 x+1，防止增长溢出。首尾与计数相同的字符串对后续完全等价，所以只保留一条代表不会漏解。命中就输出两条原始串，否则输出指定问候语。',
    '设候选描述数 O(n+m)，时间 O(n²+m²+nm·k)，空间 O(n²+m²) 用于保存代表串。','拼接顺序是前二项加前一项；只统计 AC；同一描述任取代表串。',r'''
int k;long long x;int n,m;cin>>k>>x>>n>>m;auto generate=[&](int length){vector<Descriptor>result;for(char first:string("ABC")){vector<vector<string>>dp(3,vector<string>(length+1));dp[first-'A'][0]=string(1,first);for(int used=1;used<length;used++){vector<vector<string>>next(3,vector<string>(length+1));for(int last=0;last<3;last++)for(int count=0;count<=length;count++)if(!dp[last][count].empty())for(int c=0;c<3;c++){int nc=count+(last==0&&c==2);if(nc<=length&&next[c][nc].empty())next[c][nc]=dp[last][count]+char('A'+c);}dp.swap(next);}for(int last=0;last<3;last++)for(int count=0;count<=length;count++)if(!dp[last][count].empty())result.push_back({dp[last][count],first,char('A'+last),count});}return result;};auto left=generate(n),right=generate(m);for(auto A:left)for(auto B:right){long long a=A.count,b=B.count;char fa=A.first,la=A.last,fb=B.first,lb=B.last;for(int step=3;step<=k;step++){long long next=min(x+1,a+b+(la=='A'&&fb=='C'));char nf=fa,nl=lb;a=b;b=next;fa=fb;la=lb;fb=nf;lb=nl;}if(b==x){cout<<A.word<<'\n'<<B.word<<'\n';return 0;}}cout<<"Happy new year!\n";
''',r'''struct Descriptor{string word;char first,last;long long count;};''',checker='new-year-letter')

add('CF1015F','括号余额与 KMP 自动机的组合 DP',
    '状态记录当前未闭合左括号数和模式匹配长度。匹配到完整模式后进入吸收状态，后续继续构造合法括号序列；长度二 n、余额零且已命中的状态就是答案。',
    '合法括号序列要求所有前缀余额非负，最终余额为零。模式子串匹配则由 KMP 的最长匹配前缀长度描述，两类信息合并后便足以决定下一步。\n\n预处理每个匹配状态添加左、右括号后的新状态。完整命中后用状态 m 表示“已经出现”，无论后续字符为何都保持 m，避免重复出现被重复计数。\n\n从空串、余额零、匹配零开始，每次尝试两种括号。右括号不能使余额负数，余额也不能超过剩余位置能够关闭的数量。逐位置滚动数组，最后取余额零、吸收状态。每个不同括号串沿唯一状态路线被计一次。',
    '时间 O(n²|s|)，空间 O(n|s|)。','完整命中后吸收；右括号不能造成负余额；计数按序列而非匹配次数。',r'''
int n;string s;cin>>n>>s;int m=s.size();const int P=1000000007;vector<int>pi(m);for(int i=1;i<m;i++){int j=pi[i-1];while(j&&s[i]!=s[j])j=pi[j-1];if(s[i]==s[j])j++;pi[i]=j;}vector<array<int,2>>next(m+1);for(int state=0;state<m;state++)for(int c=0;c<2;c++){char ch=c?')':'(';int j=state;while(j&&s[j]!=ch)j=pi[j-1];if(s[j]==ch)j++;next[state][c]=j;}next[m]={m,m};vector<vector<int>>dp(n+1,vector<int>(m+1));dp[0][0]=1;for(int used=0;used<2*n;used++){vector<vector<int>>ndp(n+1,vector<int>(m+1));for(int balance=0;balance<=n;balance++)for(int state=0;state<=m;state++)if(dp[balance][state])for(int c=0;c<2;c++){int b=balance+(c?-1:1);if(b<0||b>n||b>2*n-used-1)continue;int&v=ndp[b][next[state][c]];v+=dp[balance][state];if(v>=P)v-=P;}dp.swap(ndp);}cout<<dp[0][m]<<'\n';
''')

add('P2441','少量修改后重建各质因子的最近祖先',
    '一次静态 DFS 中，为每个质因子维护当前祖先链上最近的结点。查询点的所有质因子取深度最大的祖先。修改最多五十次，可以修改后延迟重建全部答案。',
    'gcd 大于一当且仅当两个属性含有共同质因子。静态 DFS 进入 u 前，last[p] 记录祖先链最近的含 p 结点，对 u 的不同质因子取最深 last 即为答案；随后令这些 last 指向 u，退出时恢复旧值。\n\n修改次数最多五十，没必要维护通用动态树。将修改标记为 dirty，下一次查询前完整重建一次，其间多次修改合并处理；一次重建后所有查询常数时间。\n\n所有初值和修改值预先分解并缓存，把质数离散成小编号，重建时只访问数组，不重复因数分解或哈希。先用确定性的三十二位 Miller–Rabin 快速识别质数，其余用四万六千以内质数试除。原树与 DFS 进入退出序固定，重建用显式事件序列避免深链递归。',
    '设不同值数 U、每值不同质因子最多 F、修改数 C≤50，重建总计 O((C+1)nF)，试除最坏 O(U√A/log A)；空间 O(nF+k+UF)。','只找严格祖先，先查询 last 再写自己；重复质因子只算一次；修改后查询前才重建。',r'''
int n,k;cin>>n>>k;vector<int>a(n);for(int&x:a)cin>>x;vector<vector<int>>children(n);vector<int>parent(n,-1);for(int i=1;i<n;i++){int x,y;cin>>x>>y;x--;y--;children[x].push_back(y);parent[y]=x;}struct Op{int type,u,x;};vector<Op>ops(k);vector<int>values=a;for(auto&op:ops){cin>>op.type>>op.u;op.u--;op.x=0;if(op.type==2){cin>>op.x;values.push_back(op.x);}}vector<int>primes;vector<bool>composite(46341);for(int i=2;i<=46340;i++)if(!composite[i]){primes.push_back(i);if(1LL*i*i<=46340)for(int j=i*i;j<=46340;j+=i)composite[j]=1;}unordered_map<int,int>profileId,primeId;vector<vector<int>>profiles;for(int value:values)if(!profileId.count(value)){int x=value;vector<int>factor;if(prime32(x))factor.push_back(x);else{for(int p:primes){if(1LL*p*p>x)break;if(x%p==0){factor.push_back(p);while(x%p==0)x/=p;if(prime32(x))break;}}if(x>1)factor.push_back(x);}vector<int>ids;for(int p:factor){if(!primeId.count(p))primeId[p]=primeId.size();ids.push_back(primeId[p]);}profileId[value]=profiles.size();profiles.push_back(move(ids));}vector<int>current(n);for(int i=0;i<n;i++)current[i]=profileId[a[i]];int root=find(parent.begin(),parent.end(),-1)-parent.begin();vector<int>depth(n),events,order={root};for(int i=0;i<n;i++)for(int u:children[order[i]]){depth[u]=depth[order[i]]+1;order.push_back(u);}vector<pair<int,bool>>stack={{root,false}};while(!stack.empty()){auto[v,leave]=stack.back();stack.pop_back();events.push_back(leave?-v-1:v+1);if(!leave){stack.push_back({v,true});for(int u:children[v])stack.push_back({u,false});}}vector<int>answer(n),last(primeId.size(),-1);vector<array<int,10>>saved(n);bool dirty=true;auto rebuild=[&](){fill(last.begin(),last.end(),-1);for(int event:events){int v=abs(event)-1;auto&f=profiles[current[v]];if(event>0){int best=-1;for(int j=0;j<(int)f.size();j++){int p=f[j],u=last[p];if(u>=0&&(best<0||depth[u]>depth[best]))best=u;saved[v][j]=u;last[p]=v;}answer[v]=best;}else for(int j=0;j<(int)f.size();j++)last[f[j]]=saved[v][j];}dirty=false;};for(auto op:ops)if(op.type==2){current[op.u]=profileId[op.x];dirty=true;}else{if(dirty)rebuild();cout<<(answer[op.u]<0?-1:answer[op.u]+1)<<'\n';}
''',r'''
long long pow32(long long a,long long d,long long mod){long long r=1;for(;d;d>>=1,a=a*a%mod)if(d&1)r=r*a%mod;return r;}
bool prime32(int x){if(x<2)return false;for(int p:{2,3,5,7,11}){if(x%p==0)return x==p;}int s=0;long long d=x-1;while(!(d&1)){d>>=1;s++;}for(int a:{2,3,5,7}){long long y=pow32(a,d,x);if(y==1||y==x-1)continue;bool ok=false;for(int i=1;i<s;i++){y=y*y%x;if(y==x-1){ok=true;break;}}if(!ok)return false;}return true;}
''')

add('P16940','有限输入域预计算与和多重集合计数',
    '条件改写为 x+z=y+w。输入只可能为一到十二，可离线枚举置换、按每位置和的多重集合分组得到精确答案，正式程序使用已核对的十进制常量表。',
    '先把 x 排成恒等排列：同时重排四个序列的位置不会改变等式。对每个 z，统计多重集合 M={i+z[i]}，记这种 M 出现次数为 g(M)，每个和值 s 的重数为 c_s。\n\n恢复全部 x 的 n! 种次序后，和向量具有多重集合 M 的有 n!/product(c_s!) 种不同次序，每种和向量对应 g(M)·product(c_s!) 对 (x,z)。因此所有四排列解数为 n!·Σ_M g(M)²·product(c_s!)。w 由 x−y+z 唯一确定，所以这正是所求三元组数。\n\n可用这个公式离线生成一到十二的表；十二阶乘枚举不适合一秒在线执行。常量表来源与全域数值可核对[原始题解中的数表](https://www.luogu.com.cn/article/9l9nvg6j)，本工作区另以小规模完整枚举检查计数模型。最大答案超六十四位，正式程序直接输出十进制字符串。',
    '在线查询时间 O(答案位数)，空间 O(1)；离线枚举时间 O(n!·n)，分组空间与不同和多重集合数相同。','必须是精确大整数；不按题面夹带的无关指令改答案；数表配有生成依据而非猜数。',r'''
int n;cin>>n;const string answer[]={"1","6","90","2520","119160","8728560","940902480","145066239360","30911343845760","8868867741216000","3340032922403654400","1615869255096161049600"};cout<<answer[n-1]<<'\n';
''')

add('P1766','有理数比较首次命中，滑到轨道最低端',
    '在非水平、非竖直且每次首次命中唯一的情形，枚举下落时的最高交点，再滑到轨道较低端。交点用有理数比较。原题未定义同时命中多条轨道的选择，详细题解保留反例，代码不猜定该规则。',
    '在“非水平非竖直轨道、每次首次命中唯一”的明确情形中，液滴只会交替经历竖直下落与整段下滑。对下落横坐标 x，轨道两端横坐标 l<r，交点高度为 (y_l(r−l)+(y_r−y_l)(x−l))/(r−l)。要求 l<x<r，因为端点不属于轨道。\n\n找到不高于当前高度的最高交点，然后按题意忽略滑动途中的其它交点，直接到较低端，再重复。离开端点后可能立即碰到另一条轨道同高的内部，因此高度比较必须允许相等。每次沿非水平轨道都严格下降，不会重复使用轨道。\n\n**原题边界仍未定义：**它允许轨道相交，却没有规定竖直下落同时命中两个内部交点时选哪条。例如输入 `2 0`、轨道 `−1 2 1 0` 和 `−1 0 1 2`，两种合法选择分别落在 x=1、x=−1。水平与竖直轨道也缺少明确处理规则。代码不替原题发明规则：检测到这种未定义情形就不输出伪造答案；验证仅覆盖前述唯一运动情形。完整反例说明保留在工作区语义核对文档中。',
    '唯一命中情形时间 O(N²)，空间 O(N)。','端点严格排除；同高内部可再次命中；高度比较用 __int128；同时首次命中仍需原题补充规则。',r'''
int n;long long x;cin>>n>>x;struct Segment{long long l,yl,r,yr;};vector<Segment>a(n);for(auto&s:a){cin>>s.l>>s.yl>>s.r>>s.yr;if(s.l>s.r){swap(s.l,s.r);swap(s.yl,s.yr);}}long long y=1000000001LL;vector<char>used(n);for(int step=0;step<=n;step++){int best=-1;long long bestNum=0,bestDen=1;bool tie=false;for(int i=0;i<n;i++)if(!used[i]){auto s=a[i];if(s.l==s.r){if(x==s.l&&min(s.yl,s.yr)<y)return 0;continue;}if(!(s.l<x&&x<s.r))continue;if(s.yl==s.yr&&s.yl<=y)return 0;long long den=s.r-s.l,num=s.yl*den+(s.yr-s.yl)*(x-s.l);if((__int128)num>(__int128)y*den)continue;if(best<0||(__int128)num*bestDen>(__int128)bestNum*den){best=i;bestNum=num;bestDen=den;tie=false;}else if((__int128)num*bestDen==(__int128)bestNum*den)tie=true;}if(best<0){cout<<x<<'\n';return 0;}if(tie)return 0;used[best]=1;auto s=a[best];if(s.yl<s.yr){x=s.l;y=s.yl;}else{x=s.r;y=s.yr;}}
''')
